const PRICING_VERSION = 'quote-v1';
const CURRENCY = 'USD';
const PRICED_UNIT = 'sqft';
const RATE_BASIS = 'rates are this firm\'s own price list as it stood when the quote was made, and the rates used are written into this breakdown';

const LINE_KINDS = { floor: 'floor', removal: 'removal', minimum: 'minimum', travel: 'travel', on_site: 'on_site' };

const REFUSALS = [
  ['pricing_not_allowed', (f) => f.row.pricing_allowed !== true],
  ['not_green',           (f) => f.row.gate_color !== 'green'],
  ['commercial',          (f) => f.row.segment === 'commercial'],
  ['no_material',         (f) => f.material === null],
  ['no_price_band',       (f) => f.material !== null && f.bands.length === 0],
  ['no_area',             (f) => f.area === null],
  ['area_not_usable',     (f) => f.row.area_comparable !== true],
  ['no_removal_rate',     (f) => f.removal && f.removalRate === null],
];

// Math.round(n * 100) reads the half-cent off a binary float, and 10.075 * 100 is 1007.4999...,
// so the cent goes down when it should go up. Rounding through the decimal exponent asks
// JavaScript for the shortest decimal that is this float, and rounds that instead.
const money = (n) => Number(`${Math.round(Number(`${n}e2`))}e-2`);

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const positive = (v) => {
  const n = num(v);
  return n !== null && n > 0 ? n : null;
};

const asBand = (b) => {
  if (!b || typeof b !== 'object') return null;
  if (String(b.unit) !== PRICED_UNIT) return null;
  const low = positive(b.rate_low);
  const high = positive(b.rate_high);
  const wastage = num(b.wastage_pct);
  const minCharge = b.min_charge === null || b.min_charge === undefined ? 0 : num(b.min_charge);
  if (low === null || high === null || high < low) return null;
  if (wastage === null || wastage < 0 || wastage > 100) return null;
  if (minCharge === null || minCharge < 0) return null;
  const label = b.product === null || b.product === undefined || b.product === ''
    ? String(b.category ?? '') : String(b.product);
  return { label, low, high, wastage, minCharge };
};

const asRate = (r) => {
  if (!r || typeof r !== 'object') return null;
  const low = positive(r.val_low);
  const high = positive(r.val_high);
  if (low === null || high === null || high < low) return null;
  return { low, high };
};

const priceOne = (row) => {
  const material = row.material_category === null || row.material_category === undefined
    || row.material_category === '' ? null : String(row.material_category);
  const area = positive(row.area_sqft);
  const bands = (Array.isArray(row.bands) ? row.bands : []).map(asBand).filter((b) => b !== null);
  const removal = row.old_floor_removal === true;
  const rules = row.rules && typeof row.rules === 'object' ? row.rules : {};
  const removalRate = removal ? asRate(rules.old_floor_removal) : null;

  // Georgetown, San Marcos, Wimberley and the rest are inside what this firm covers and outside
  // what the rates already pay for -- core towns have the travel inside the rate, edge ones do not.
  // Until now `edge` produced the sentence "travel fee applies" and never became money, so the
  // quote was short by the drive on every job that had one.
  const travelRate = row.zone === 'edge' ? asRate(rules.travel_fee) : null;

  // What a letter cannot put a price on. Named with the firm's own per-step rate so the customer
  // knows the order of magnitude, and deliberately given no quantity and no money: counting stairs
  // from an email is guessing at a number the owner then has to honour.
  const onSiteRates = row.on_site_rates && typeof row.on_site_rates === 'object' ? row.on_site_rates : {};
  const onSiteItems = (Array.isArray(row.on_site_items) ? row.on_site_items : [])
    .filter((item) => asRate(onSiteRates[item]) !== null);

  const facts = { row, material, area, bands, removal, removalRate };
  const refusals = REFUSALS.filter(([, applies]) => applies(facts)).map(([code]) => code);

  const stamped = {
    gmail_message_id: row.gmail_message_id === undefined ? null : row.gmail_message_id,
    pricing_version: PRICING_VERSION,
    currency: CURRENCY,
  };

  if (refusals.length) {
    return {
      ...stamped,
      priceable: false,
      refusals,
      subtotal_low: null,
      subtotal_high: null,
      total_low: null,
      total_high: null,
      breakdown: null,
    };
  }

  const removalLow = removalRate ? money(area * removalRate.low) : 0;
  const removalHigh = removalRate ? money(area * removalRate.high) : 0;
  const removalLines = removalRate ? [{
    kind: LINE_KINDS.removal,
    label: 'old floor removal and disposal',
    source: 'pricing_rules.old_floor_removal',
    unit: PRICED_UNIT,
    quantity: money(area),
    rate_low: removalRate.low,
    rate_high: removalRate.high,
    low: removalLow,
    high: removalHigh,
  }] : [];

  const travelLow = travelRate ? travelRate.low : 0;
  const travelHigh = travelRate ? travelRate.high : 0;
  const travelLines = travelRate ? [{
    kind: LINE_KINDS.travel,
    label: 'travel to the edge of the service area',
    source: 'pricing_rules.travel_fee',
    unit: 'visit',
    quantity: 1,
    rate_low: travelRate.low,
    rate_high: travelRate.high,
    low: travelLow,
    high: travelHigh,
  }] : [];

  const onSiteLines = onSiteItems.map((item) => {
    const rate = asRate(onSiteRates[item]);
    return {
      kind: LINE_KINDS.on_site,
      label: item,
      source: 'price_bands',
      unit: String(onSiteRates[item].unit ?? 'each'),
      quantity: null,
      rate_low: rate.low,
      rate_high: rate.high,
      low: null,
      high: null,
    };
  });

  const floorLines = [];
  const minimumLines = [];
  const priced = bands.map((b) => {
    // square feet rounded to cents is not a unit of anything. Rounding it here and then
    // multiplying by a rate loses precision before the only place it means money.
    const quantity = area * (1 + b.wastage / 100);
    const floorLow = money(quantity * b.low);
    const floorHigh = money(quantity * b.high);
    floorLines.push({
      kind: LINE_KINDS.floor,
      label: b.label,
      source: 'price_bands',
      unit: PRICED_UNIT,
      quantity: money(quantity),
      wastage_pct: b.wastage,
      rate_low: b.low,
      rate_high: b.high,
      low: floorLow,
      high: floorHigh,
    });

    const subLow = money(floorLow + removalLow);
    const subHigh = money(floorHigh + removalHigh);
    // after the minimum, not inside it: the minimum charge is what the floor work is worth turning
    // up for, and the drive is not floor work. Folding travel in would let a big enough job swallow
    // it and a small one charge it twice over.
    const totLow = money(Math.max(subLow, b.minCharge) + travelLow);
    const totHigh = money(Math.max(subHigh, b.minCharge) + travelHigh);
    if (totLow - travelLow > subLow || totHigh - travelHigh > subHigh) {
      minimumLines.push({
        kind: LINE_KINDS.minimum,
        label: b.label,
        source: 'price_bands.min_charge',
        amount: b.minCharge,
        applied_to_low: totLow - travelLow > subLow,
        applied_to_high: totHigh - travelHigh > subHigh,
      });
    }
    return { subLow, subHigh, totLow, totHigh };
  });

  return {
    ...stamped,
    priceable: true,
    refusals: [],
    subtotal_low: money(Math.min(...priced.map((p) => p.subLow))),
    subtotal_high: money(Math.max(...priced.map((p) => p.subHigh))),
    total_low: money(Math.min(...priced.map((p) => p.totLow))),
    total_high: money(Math.max(...priced.map((p) => p.totHigh))),
    breakdown: {
      basis: RATE_BASIS,
      material_category: material,
      area_sqft: money(area),
      area_status: row.area_status,
      old_floor_removal: removal,
      lines: [...floorLines, ...removalLines, ...minimumLines, ...travelLines, ...onSiteLines],
    },
  };
};

return $input.all().map((item, i) => ({
  json: priceOne(item.json || {}),
  pairedItem: { item: i },
}));

// Where a letter goes when nobody may read it first. The same address the rest of the system
// writes to, and the only address in this file that is not the customer's.
const OWNER = 'flooring.demo.austin@gmail.com';

// A rate reads as $4 or $4.50; a total reads as $5,600 and never as $5600.
const money = (n) => {
  const v = Number(n);
  return `$${v.toLocaleString('en-US', {
    minimumFractionDigits: Number.isInteger(v) ? 0 : 2,
    maximumFractionDigits: 2,
  })}`;
};

// What the job costs per square foot, as a person reads it. The numbers come from price_bands and
// the sentence around them from reply_templates; this only lays them out. A range is a published
// rate, not a quote, so it can be said before anything else is known.
const rateBlock = (asked) => {
  const bands = typeof asked.bands === 'string' ? JSON.parse(asked.bands) : asked.bands;
  const preamble = String(asked.rates_preamble || '').trim();
  if (!Array.isArray(bands) || !bands.length || !preamble) return '';

  const lines = bands
    .map((b) => `  ${b.product}: ${money(b.rate_low)}-${money(b.rate_high)} per sq ft`)
    .join('\n');

  // A total only when the area is real and the job is one the firm would take. A quantity is never
  // invented, and a figure shown to somebody outside the area is an invitation followed by a
  // refusal.
  const area = Number(asked.area_sqft);
  const worth = asked.worth_illustrating === true || asked.worth_illustrating === 't';
  const totals = (area > 0 && worth && bands.length)
    ? `\n\nFor ${area.toLocaleString('en-US')} sq ft that comes to roughly `
      + `${money(Math.round(area * Math.min(...bands.map((b) => Number(b.rate_low)))))} to `
      + `${money(Math.round(area * Math.max(...bands.map((b) => Number(b.rate_high)))))}.`
    : '';

  return `${preamble}\n\n${lines}${totals}\n\n`;
};

const composeOne = (asked) => {
  // Joining strings, nothing else. Every sentence here was written by a person and is stored in
  // reply_templates, so changing how the firm sounds is an edit in the database rather than a
  // deployment -- and nothing in this file decides what the firm says.
  const signature = String(asked.signature || '');

  // A refusal beats a number, and it beats a question. Somebody who wrote "Dallas" has told us
  // where they are; asking them again is worse than saying no, and quoting them a rate is worse
  // still -- it is an invitation to a job that will then be turned down.
  const outOfArea = asked.out_of_area === true || asked.out_of_area === 't';
  const refusal = String(asked.out_of_area_words || '').trim();
  const body = outOfArea ? refusal : String(asked.body || '').trim();

  if (!body) {
    throw new Error(outOfArea
      ? 'no wording is stored for a property outside the service area, and asking somebody in '
        + 'Dallas where they are is worse than saying nothing: reply_templates is missing '
        + '"out_of_area"'
      : `no template is stored for ${asked.template_key || 'this combination'} -- `
        + 'reply_templates is missing a row, and sending an empty letter is worse than sending none');
  }

  // A lead forwarded by a platform with no reply-to leaves no address to answer. The router already
  // says so through needs_sender_extraction, and a letter with nobody in the To field is not a
  // letter. Refusing here sends it to the error lane, where a person can find the address; sending
  // it would fail somewhere less visible, or worse, reach the platform instead of the customer.
  const to = String(asked.contact_email || '').trim();
  if (!to) {
    throw new Error('there is no address to answer: this arrived through a platform that forwarded '
      + 'no reply-to, and the customer cannot be reached without one');
  }

  // Where it goes is the stored sentence's decision, not this file's. A sentence that may not go
  // out alone still gets written -- it goes to the owner, marked as not sent, so she can read it
  // and decide. Nothing is silently dropped and nothing reaches a customer unread.
  const alone = asked.may_go_alone === true || asked.may_go_alone === 't';

  // The customer's copy is a reply, so the subject and the thread are Gmail's to continue and not
  // ours to invent -- one message id is the whole of it. Only the owner's copy needs a subject,
  // because it starts a new letter, and it says what it is at a glance.
  return {
    gmail_message_id: asked.gmail_message_id,
    order_id: asked.order_id,
    asking_for: asked.asking_for,
    to: alone ? to : OWNER,
    reaches_the_customer: alone,
    thread_id: alone ? asked.thread_id : null,
    subject: alone ? null : `Not sent -- a question for ${to}`,
    out_of_area: outOfArea,
    body: alone ? (outOfArea ? body : rateBlock(asked) + body) + signature
      : `This was composed for ${to} and not sent, because the wording it uses is marked as `
        + `needing a person first.\n\nAsking for: ${asked.asking_for}\n\n---\n\n`
        + `${outOfArea ? body : rateBlock(asked) + body}${signature}`,
  };
};

// One letter per enquiry. A poll that finds two customers hands this node both at once, and the
// first version of it answered whichever came first and dropped the other -- silently, with their
// message already marked as handled.
return $input.all().map((item, i) => ({
  json: composeOne(item.json || {}),
  pairedItem: { item: i },
}));

// A letter carrying a price, written for the customer and left where only the owner can send it.
//
// It is composed here and put in the owner's mailbox as a draft, in the customer's own conversation.
// The owner reads it, changes whatever wants changing, and presses send. Nothing here decides that it goes:
// the draft has no way of leaving on its own, which is a stronger guarantee than the one this
// replaced. That one mailed the letter to the owner and read the reply with a pattern -- so a figure
// reached a customer whenever the pattern matched, and "almost right, let me change a word" was
// read as a refusal, because `change` is one of the words that means no.
//
// One thing comes out of this node: the letter the customer would read. Telling the owner that a
// draft is waiting is a separate step in a separate file, and deliberately so -- what is said to the owner
// carries figures and what the firm is unsure of, and a check in this repository refuses to let the
// two be written a few lines apart. Composing both here would put the owner's sentence one mistaken
// variable away from the customer's letter.

const money = (n) => `$${Number(n).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

// The breakdown as a person reads it, not as it is stored. Each line already knows what it is, what
// it was worked out from and at what rate, because the arithmetic wrote all three down when it ran.
const readable = (lines) => (lines || []).map((line) => {
  if (line.kind === 'minimum') {
    return `  ${line.label}: minimum charge ${money(line.amount)} applies`;
  }
  // a flat charge for turning up, not a rate on anything: "1 visit at $50-$150" reads as though
  // there were a price per visit and we had chosen one
  if (line.kind === 'on_site') {
    return `  ${line.label}: counted on site, not from an email — they run `
      + `${money(line.rate_low)}-${money(line.rate_high)} ${line.unit}, and are not in the figures above`;
  }
  if (line.kind === 'travel') {
    return `  ${line.label}: ${money(line.low)}${line.low === line.high ? '' : ` to ${money(line.high)}`}`;
  }
  const rate = line.rate_low === line.rate_high
    ? `${money(line.rate_low)}/${line.unit}`
    : `${money(line.rate_low)}-${money(line.rate_high)}/${line.unit}`;
  const waste = line.wastage_pct ? ` (incl. ${line.wastage_pct}% waste)` : '';
  return `  ${line.label}: ${Number(line.quantity).toLocaleString('en-US')} ${line.unit}${waste} at ${rate}`
    + `\n      ${money(line.low)} to ${money(line.high)}`;
}).join('\n');

// Gmail threads on the subject as well as on the thread id, so the reply carries the subject it is
// replying to. Prefixed once and never twice: a conversation five letters deep would otherwise read
// "Re: Re: Re: Re: Laminate".
//
// An empty subject stays empty. Gmail will only attach a draft to a thread whose subject matches,
// so inventing one for a letter that arrived without a subject puts the draft beside the
// conversation instead of inside it -- and the whole point of this is that the customer's own
// conversation is where it waits.
const replyTo = (subject) => {
  const said = String(subject || '').trim();
  if (!said) return '';
  return /^re\s*:/i.test(said) ? said : `Re: ${said}`;
};

return $input.all().map((item, i) => {
  const q = item.json || {};

  if (q.ready_to_write !== true && q.ready_to_write !== 't') {
    throw new Error('there is no offer to write about, or no wording stored for one: '
      + `offer ${q.offer_id || 'unknown'} with total ${q.total_low === null ? 'nothing' : q.total_low}`);
  }

  // No address, no draft. A lead forwarded by a platform with no reply-to leaves nobody to write
  // to, and a draft addressed to an empty string is one somebody sends by accident.
  const who = String(q.contact_email || '').trim();
  if (!who) {
    throw new Error('there is no address to send this quote to: this arrived through a platform '
      + 'that forwarded no reply-to, and a draft with nobody in the To field is not a letter');
  }

  const breakdown = typeof q.breakdown === 'string' ? JSON.parse(q.breakdown) : (q.breakdown || {});
  const range = `${money(q.total_low)} to ${money(q.total_high)}`;
  // the town is stored the way the customer wrote it, lowercased for matching. A letter is not a
  // lookup key.
  const town = q.city ? String(q.city).replace(/\b[a-z]/g, (c) => c.toUpperCase()) : null;
  const job = [q.material_category, q.area_sqft ? `${Number(q.area_sqft).toLocaleString('en-US')} sq ft` : null,
    town].filter(Boolean).join(', ');

  // What the customer would read, and the whole of what the draft contains. No note to the owner
  // wrapped around it any more: it is read inside the owner's own mail client, about to be sent, and
  // anything above it would be one deleted paragraph away from reaching the customer.
  const forTheCustomer = `${q.opening}\n\n${job}\n\n${readable(breakdown.lines)}\n\n`
    + `All in: ${range}.\n\n${q.closing}${q.signature || ''}`;

  return {
    json: {
      gmail_message_id: q.gmail_message_id,
      offer_id: q.offer_id,
      order_id: q.order_id,
      // the draft: the customer's letter, in the customer's conversation
      write_to: who,
      thread_id: q.thread_id,
      subject: replyTo(q.subject),
      body: forTheCustomer,
      the_letter_itself: forTheCustomer,
    },
    pairedItem: { item: i },
  };
});

// A letter that answers what somebody asked, and then asks for what a price would need.
//
// Two sentences a person wrote: the answer, which lives in the services table so that changing what
// the firm says about tile is one edit in one place, and a closing that asks for the parameters.
// Nothing here decides what the firm does or does not install.

const OWNER = 'flooring.demo.austin@gmail.com';

// A rate reads as $4 or $4.50, never as $4.5.
const money = (n) => {
  const v = Number(n);
  return `$${v.toLocaleString('en-US', {
    minimumFractionDigits: Number.isInteger(v) ? 0 : 2,
    maximumFractionDigits: 2,
  })}`;
};

// What the work costs per square foot, laid out for a person. The numbers come from price_bands
// and the sentence around them from reply_templates; nothing here decides what the firm charges.
//
// A published range is not a quote. It commits nobody, it needs no measurements, and it is the one
// thing somebody wants to know before anything else -- so withholding it until they have answered
// two questions is the pause this desk exists to remove.
const rateBlock = (asked) => {
  const bands = typeof asked.bands === 'string' ? JSON.parse(asked.bands) : asked.bands;
  const preamble = String(asked.rates_preamble || '').trim();
  if (!Array.isArray(bands) || !bands.length || !preamble) return '';
  const lines = bands
    .map((b) => `  ${b.product}: ${money(b.rate_low)}-${money(b.rate_high)} per sq ft`)
    .join('\n');
  return `\n\n${preamble}\n\n${lines}`;
};

return $input.all().map((item, i) => {
  const q = item.json || {};
  const worth = q.worth_answering === true || q.worth_answering === 't';

  if (!worth) {
    throw new Error('there is nothing to answer here: '
      + `asked about ${q.service_asked_about || 'nothing recognised'}, `
      + `${q.answer ? 'with' : 'without'} an answer stored, `
      + `${q.contact_email ? 'with' : 'without'} an address to reply to`);
  }

  const weDo = q.we_do === true || q.we_do === 't';
  const answer = String(q.answer).trim();
  const closing = String(q.what_next || '').trim();
  const signature = String(q.signature || '');

  // Only a service the firm actually offers gets rates and a request for the parameters. Quoting a
  // rate for work that was just declined, or asking for the square footage of it, reads as not
  // having listened -- and the refusal is the whole of what that letter has to say.
  const rates = weDo ? rateBlock(q) : '';
  const body = weDo && closing
    ? `${answer}${rates}\n\n${closing}${signature}`
    : `${answer}${signature}`;

  return {
    json: {
      gmail_message_id: q.gmail_message_id,
      service_asked_about: q.service_asked_about,
      we_do: weDo,
      to: q.contact_email,
      reply_to: q.gmail_message_id,
      thread_id: q.thread_id,
      asks_for_more: weDo && Boolean(closing),
      quoted_a_rate: weDo && rates !== '',
      body,
    },
    pairedItem: { item: i },
  };
});

// The line that tells the owner a quote is sitting in the owner's drafts.
//
// It exists because a draft announces itself to nobody. The letter the desk used to send
// arrived in the inbox and was impossible to miss; a draft lies in a folder until somebody
// remembers to look, and a quote nobody remembers is a customer nobody answered.
//
// Written here rather than beside the letter itself, and that separation is the point. This carries
// the figures and whether the gate held the enquiry for a person -- things the customer must never
// read. A check in this repository refuses to let a customer letter be composed in a file that
// reaches for what the owner is told, and composing both in one place would put this sentence one
// mistaken variable away from the draft.
//
// It never carries the letter. The letter lives in exactly one place, which is the draft about to
// be sent: two copies of it would be two things to keep in step.

const money = (n) => `$${Number(n).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

return $input.all().map((item, i) => {
  const q = $('What the quote letter needs').itemMatching(i)?.json || {};
  const drafted = $('Compose the quote').itemMatching(i)?.json || {};

  const range = `${money(q.total_low)} to ${money(q.total_high)}`;
  const town = q.city ? String(q.city).replace(/\b[a-z]/g, (c) => c.toUpperCase()) : null;
  const job = [q.material_category, q.area_sqft ? `${Number(q.area_sqft).toLocaleString('en-US')} sq ft` : null,
    town].filter(Boolean).join(', ');

  const message = [
    `📝 *A quote is drafted and waiting — ${range}*`,
    `✉️ ${drafted.write_to || q.contact_email || 'no address on file'}`,
    `🧾 ${job || 'job not described'}`,
    '',
    q.auto_blocked
      ? 'The gate held this enquiry for a person before anything automatic happened to it. Read the '
        + 'enquiry as well as the letter before you send.'
      : 'It is in your drafts, in their own conversation. Read it, change whatever you want to '
        + 'change, and send it. Nothing goes until you do.',
  ].join('\n');

  return { json: { ...item.json, message }, pairedItem: { item: i } };
});
